const {app,BrowserWindow}=require('electron'),fs=require('node:fs'),path=require('node:path')
const result=path.join(process.env.RALLY_TEST_FIXTURE,'result.txt')
app.whenReady().then(async()=>{
const win=new BrowserWindow({show:false,width:1400,height:950,webPreferences:{backgroundThrottling:false,preload:path.join(__dirname,'preload.cjs')}})
await win.loadFile(process.env.RALLY_TEST_DIST)
const status=await win.webContents.executeJavaScript('('+ (async()=>{
  const pause=ms=>new Promise(r=>setTimeout(r,ms))
  const wait=async(fn,label)=>{for(let i=0;i<100;i++){const v=fn();if(v)return v;await pause(80)}throw Error(label)}
  await wait(()=>document.querySelector('[data-enter-demo]'),'demo')
  document.querySelector('[data-enter-demo]').click()
  await wait(()=>[...document.querySelectorAll('button')].some(b=>b.textContent.trim()==='文档中心'),'sidebar')
  const nav=name=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim()===name).click()
  nav('文档中心')
  await wait(()=>document.querySelector('[data-doc-row]'),'docs')
  document.querySelector('[data-doc-row]').click()
  await wait(()=>document.querySelector('[data-doc-reader]'),'reader')
  if(!document.querySelector('[data-docs=root] input[aria-label="搜索文档"]'))throw Error('tree disappeared')
  const pane=document.querySelector('[data-doc-pane]')
  if(pane.getBoundingClientRect().left<400)throw Error('reader not on right')
  document.querySelector('[aria-label="全屏文档"]').click()
  await wait(()=>document.querySelector('[data-fullscreen]'),'fullscreen')
  document.querySelector('[aria-label="退出全屏"]').click()
  await pause(80)
  document.querySelector('[data-doc-new]').click()
  await wait(()=>document.querySelector('[data-doc-editor]'),'editor')
  const title=document.querySelector('.doc-editor-title')
  const set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set
  set.call(title,'回归测试文档');title.dispatchEvent(new Event('input',{bubbles:true}))
  await pause(150)
  const originalConfirm=window.confirm
  let warned=false
  window.confirm=()=>{warned=true;return false}
  document.querySelector('[data-doc-id]').click()
  await pause(80)
  if(!warned || !document.querySelector('[data-doc-editor]') || document.querySelector('.doc-editor-title').value!=='回归测试文档')throw Error('unsaved navigation discarded draft')
  window.confirm=originalConfirm
  document.querySelector('[aria-label="全屏文档"]').click()
  await pause(50)
  document.querySelector('[aria-label="退出全屏"]').click()
  if(document.querySelector('.doc-editor-title').value!=='回归测试文档')throw Error('fullscreen lost draft')
  nav('任务看板')
  await wait(()=>document.querySelector('[data-task-row]'),'tasks')
  if(document.querySelectorAll('[data-status]').length!==4)throw Error('columns')
  const card=document.querySelector('[data-task-row]'),r=card.getBoundingClientRect()
  window.__drag={id:card.dataset.taskRow,x:r.left+65,y:r.top+45,left:r.left,top:r.top}
  return 'PASS document right pane, persistent navigation, fullscreen read/edit preserves draft; board ready'

}).toString()+')()',true)
await new Promise(r=>setTimeout(r,300))
win.webContents.debugger.attach('1.3')
const d=await win.webContents.executeJavaScript('window.__drag')
const mouse=async(type,x,y,pressed=false)=>win.webContents.debugger.sendCommand('Input.dispatchMouseEvent',{type,x,y,button:type==='mouseMoved'?'none':'left',buttons:pressed?1:0,clickCount:type==='mouseMoved'?0:1})
await mouse('mouseMoved',d.x,d.y)
await mouse('mousePressed',d.x,d.y,true)
await mouse('mouseMoved',d.x+12,d.y+10,true)
await new Promise(r=>setTimeout(r,180))
await mouse('mouseMoved',d.x+130,d.y+120,true)
await new Promise(r=>setTimeout(r,100))
const overlay=await win.webContents.executeJavaScript('(()=>{const e=document.querySelector("[data-task-id=\\"'+d.id+'\\"]:not([data-task-row] [data-task-id])");const r=e?.getBoundingClientRect();return r?{left:r.left,top:r.top}:null})()')
if(!overlay || Math.abs(overlay.left-(d.left+130))>5 || Math.abs(overlay.top-(d.top+120))>5)throw Error('drag offset '+JSON.stringify({overlay,expected:{left:d.left+130,top:d.top+120}}))
const target=await win.webContents.executeJavaScript('(()=>{const r=document.querySelectorAll("[data-status]")[2].getBoundingClientRect();return {x:r.left+80,y:r.top+65}})()')
await mouse('mouseMoved',target.x,target.y,true)
await new Promise(r=>setTimeout(r,120))
await mouse('mouseReleased',target.x,target.y)
await new Promise(r=>setTimeout(r,300))
const moved=await win.webContents.executeJavaScript('document.querySelector("[data-task-row=\\"'+d.id+'\\"]").closest("[data-status]").dataset.status')
if(moved!=='doing')throw Error('move failed '+moved)

fs.writeFileSync(path.join(process.env.RALLY_TEST_FIXTURE,'login.png'),(await win.webContents.capturePage()).toPNG())
fs.writeFileSync(result,status+'; native pointer overlay matched grab offset and cross-column move persisted')
}).catch(e=>fs.writeFileSync(result,String(e))).finally(()=>app.exit())
setTimeout(()=>{fs.writeFileSync(result,'timeout');app.exit(1)},45000).unref()
